const imageUrl = (id, width = 800) => {
  if (id?.startsWith('/api/')) return `${new URL(API, window.location.origin).origin}${id}`;
  if (id?.startsWith('/')) return id;
  if (id?.startsWith('http')) {
    try {
      const url = new URL(id);
      if (url.hostname === 'images.unsplash.com') {
        url.searchParams.set('w', String(width));
        url.searchParams.set('q', String(width < 500 ? 65 : 68));
        url.searchParams.set('auto', 'format');
      }
      return url.toString();
    } catch { return id; }
  }
  return `https://images.unsplash.com/${id}?auto=format&fit=crop&w=${width}&q=${width<500?65:68}`;
};
const money = n => `₹${n.toLocaleString('en-IN')}`;
const checkoutAttemptStorageKey = 'thara-checkout-attempt';
const cartSignature = cart => JSON.stringify(cart.map(item => [String(item.id), item.size, item.qty]));
function getCheckoutAttemptKey(cart) {
  const signature = cartSignature(cart);
  try {
    const saved = JSON.parse(sessionStorage.getItem(checkoutAttemptStorageKey) || 'null');
    if (saved?.signature === signature && saved.key) return saved.key;
    const key = crypto.randomUUID();
    sessionStorage.setItem(checkoutAttemptStorageKey, JSON.stringify({ signature, key }));
    return key;
  } catch {
    return crypto.randomUUID();
  }
}
function clearCheckoutAttemptKey() {
  try { sessionStorage.removeItem(checkoutAttemptStorageKey); } catch {}
}
function resolveCheckoutCart(cart, liveCatalog) {
  return cart.map(item => {
    const normalize = value => String(value || '').normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    const liveProduct = liveCatalog.find(product => String(product.id) === String(item.id)) || liveCatalog.find(product => normalize(product.name) === normalize(item.name));
    if (!liveProduct || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(liveProduct.id))) throw new Error(`${item.name || 'A piece in your bag'} is no longer available. Remove it from your bag and add it again.`);
    const variant = liveProduct.variants?.find(option => String(option.id) === String(item.variantId)) || liveProduct.variants?.find(option => Object.entries(option.options || {}).some(([key, value]) => key.toLowerCase() === 'size' && String(value) === String(item.size)));
    if (liveProduct.variants?.length && !variant) throw new Error(`Please select an available size for ${liveProduct.name}.`);
    return { ...liveProduct, ...(variant ? { variantId: variant.id, sku: variant.sku, price: variant.pricePaise / 100 } : { variantId: undefined }), size: item.size, qty: item.qty, key: `${liveProduct.id}-${variant?.id || item.size}` };
  });
}
function colorHistogram(source){return new Promise((resolve,reject)=>{const image=new Image();if(typeof source==='string'&&source.startsWith('http'))image.crossOrigin='anonymous';image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=24;canvas.height=24;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,24,24);const pixels=context.getImageData(0,0,24,24).data;const bins=new Array(12).fill(0);for(let i=0;i<pixels.length;i+=4){if(pixels[i+3]<80)continue;bins[Math.min(3,pixels[i]>>6)]++;bins[4+Math.min(3,pixels[i+1]>>6)]++;bins[8+Math.min(3,pixels[i+2]>>6)]++;}const total=bins.reduce((a,b)=>a+b,0)||1;resolve(bins.map(x=>x/total));};image.onerror=()=>reject(new Error('Image could not be read.'));image.src=source;});}
let razorpayCheckoutPromise;
function loadRazorpayCheckout(){
  if(window.Razorpay)return Promise.resolve();
  if(razorpayCheckoutPromise)return razorpayCheckoutPromise;
  razorpayCheckoutPromise=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    const timeout=window.setTimeout(()=>{script.remove();reject(new Error('Razorpay Checkout took too long to load. Check the connection or browser content blockers and try again.'));},15000);
    script.src='https://checkout.razorpay.com/v1/checkout.js';
    script.async=true;
    script.onload=()=>{window.clearTimeout(timeout);if(window.Razorpay)resolve();else reject(new Error('Razorpay Checkout loaded without its payment interface. Please try again.'));};
    script.onerror=()=>{window.clearTimeout(timeout);script.remove();reject(new Error('Razorpay Checkout was blocked or could not be reached. Check the site security policy and try again.'));};
    document.head.appendChild(script);
  }).catch(error=>{razorpayCheckoutPromise=null;throw error;});
  return razorpayCheckoutPromise;
}

